import com.unitepaintball.app.SharedFeaturePolicy;
public final class SharedFeaturePolicyTest {public static void main(String[] args){String base="https://unite-paintball-jura.lacroixnathan39300.chatgpt.site";if(!SharedFeaturePolicy.ownUrl(base+"/admin",base))throw new AssertionError();for(String bad:new String[]{"http://"+base.substring(8),"https://evil.example",base+":444","https://attacker@"+base.substring(8)})if(SharedFeaturePolicy.ownUrl(bad,base))throw new AssertionError(bad);for(String bad:new String[]{"//evil.example","https://evil.example","/\\evil.example","/x\ny"})if(!SharedFeaturePolicy.path(bad).equals("/fonctionnalites"))throw new AssertionError();if(!SharedFeaturePolicy.path("/reservations?gift=UP-ABC").equals("/reservations?gift=UP-ABC"))throw new AssertionError();if(!SharedFeaturePolicy.pageForApi("/api/admin-gamification?scope=config").equals("/admin/gamification"))throw new AssertionError();if(SharedFeaturePolicy.mimeTypes(new String[]{""}).length!=0)throw new AssertionError();if(!java.util.Arrays.equals(SharedFeaturePolicy.mimeTypes(new String[]{"image/*,video/*"}),new String[]{"image/*","video/*"}))throw new AssertionError();if(!java.util.Arrays.equals(SharedFeaturePolicy.mimeTypes(new String[]{".json,.pdf"}),new String[]{"application/json","application/pdf"}))throw new AssertionError();System.out.println("14 contrôles navigation et fichiers partagés OK");}}
